public class AccountPaymentBatch {void pay(){System.out.println("Paid in one go (day-scholar account)");}static class Hostel extends AccountPaymentBatch{void pay(){System.out.println("Paid in two installments (hostel account)");}}static void processPayment(AccountPaymentBatch a,double amount){a.pay();}public static void main(String[]x){AccountPaymentBatch[]a={new Hostel(),new Hostel(),new AccountPaymentBatch(),new AccountPaymentBatch()};int h=0,d=0;for(int i=0;i<a.length;i++){processPayment(a[i],60000);if(a[i] instanceof Hostel)h++;else d++;}System.out.println("Hostel accounts processed: "+h+" | Day-scholar accounts processed: "+d);}}
